<form wire:submit="saveExercise" class="sandbox-form" @input="dirty=true">
    <flux:input label="Exercise title" wire:model="exerciseForm.title" placeholder="A question, a scene, a possibility" />
    <flux:textarea label="What are we exploring?" wire:model="exerciseForm.purpose" rows="3" />
    <flux:textarea label="Instructions for this exercise" wire:model="exerciseForm.instructions" rows="3" />
    <details wire:ignore.self><summary>Retained summary</summary><flux:textarea label="Your working summary" wire:model="exerciseForm.summary" rows="5" /><p class="sandbox-help">Original messages remain saved. Only accepting a generated working summary replaces its covered messages in future requests.</p></details>
    <fieldset><legend>Established world context</legend><p class="sandbox-help">Choose the records to send. Sandbox ideas, connections and this conversation are included automatically.</p><div class="sandbox-context-choices">@forelse($catalogue as $record)<label><input type="checkbox" wire:model="exerciseForm.context_keys" value="{{ $record['key'] }}"> {{ $record['name'] }} <small>{{ $record['kind'] }}</small></label>@empty<p>No established world records available.</p>@endforelse</div></fieldset>
    @if($chapters->isNotEmpty())<fieldset><legend>Source collection</legend><p class="sandbox-help">Choose the chapters the assistant may consult. It will find and read passages for each question. You can select the whole manuscript without knowing where a character appears.</p><label><input type="checkbox" :checked="$wire.exerciseForm.passages.length === {{ $chapters->count() }}" x-on:change="$wire.set('exerciseForm.passages', $event.target.checked ? @js($chapters->pluck('id')->map(fn($id)=>(string)$id)->all()) : []);dirty=true"> All available chapters</label><div class="sandbox-context-choices">@foreach($chapters->groupBy('manuscript_id') as $bookChapters)
